// Render helper
function renderIcon(name, size = 16, className = '') {
  const svg = Icons[name] || Icons.activity;
  return svg.replace('width="16"', `width="${size}"`)
            .replace('height="16"', `height="${size}"`)
            .replace('<svg', `<svg class="industrial-icon ${className}"`);
}

window.Icons = Icons;
window.renderIcon = renderIcon;
